#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define MOD 1000000007LL

typedef struct {
    long long a;
    long long b;
} Effect;

static inline long long read_ll() {
    long long x = 0;
    int c = getchar_unlocked();
    while (c <= ' ' && c != EOF) {
        c = getchar_unlocked();
    }
    if (c == EOF) return 0;
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar_unlocked();
    }
    return x;
}

static inline void print_ll(long long x) {
    if (x == 0) {
        putchar_unlocked('0');
        putchar_unlocked('\n');
        return;
    }
    char buf[25];
    int idx = 0;
    while (x > 0) {
        buf[idx++] = (char)('0' + (x % 10));
        x /= 10;
    }
    while (idx > 0) {
        putchar_unlocked(buf[--idx]);
    }
    putchar_unlocked('\n');
}

long long power_mod(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (__int128)res * base % MOD;
        base = (__int128)base * base % MOD;
        exp >>= 1;
    }
    return res;
}

long long mod_inv(long long n) {
    return power_mod(n, MOD - 2);
}

int cmp_meals(const void* p1, const void* p2) {
    const Effect* m1 = (const Effect*)p1;
    const Effect* m2 = (const Effect*)p2;
    __int128 left = (__int128)m1->b * (m2->a - 1);
    __int128 right = (__int128)m2->b * (m1->a - 1);
    if (left > right) return -1;
    if (left < right) return 1;
    return 0;
}

int cmp_spells(const void* p1, const void* p2) {
    const Effect* s1 = (const Effect*)p1;
    const Effect* s2 = (const Effect*)p2;
    if (s1->a != s2->a) {
        return (s1->a < s2->a) ? -1 : 1;
    }
    if (s1->b != s2->b) {
        return (s1->b > s2->b) ? -1 : 1;
    }
    return 0;
}

Effect spells_raw[100005];
Effect unique_spells[100005];
Effect cht[100005];
Effect meals[100005];

int query_cht(int H, long long x) {
    int low = 0, high = H - 1;
    while (low < high) {
        int mid = (low + high) / 2;
        __int128 v1 = (__int128)cht[mid].a * x + cht[mid].b;
        __int128 v2 = (__int128)cht[mid + 1].a * x + cht[mid + 1].b;
        if (v2 >= v1) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    return low;
}

int main() {
    int N = (int)read_ll();
    int M = (int)read_ll();
    long long K = read_ll();

    for (int i = 0; i < N; i++) {
        spells_raw[i].a = read_ll();
    }
    for (int i = 0; i < N; i++) {
        spells_raw[i].b = read_ll();
    }

    for (int i = 0; i < M; i++) {
        meals[i].a = read_ll();
    }
    for (int i = 0; i < M; i++) {
        meals[i].b = read_ll();
    }

    qsort(meals, M, sizeof(Effect), cmp_meals);
    long long A_ref = 1, B_ref = 0;
    for (int i = 0; i < M; i++) {
        long long a = meals[i].a % MOD;
        long long b = meals[i].b % MOD;
        A_ref = ((__int128)A_ref * a) % MOD;
        B_ref = ((__int128)B_ref * a + b) % MOD;
    }

    qsort(spells_raw, N, sizeof(Effect), cmp_spells);
    int unique_N = 0;
    for (int i = 0; i < N; i++) {
        if (i > 0 && spells_raw[i].a == spells_raw[i - 1].a) {
            continue;
        }
        unique_spells[unique_N++] = spells_raw[i];
    }

    int H = 0;
    for (int i = 0; i < unique_N; i++) {
        while (H >= 2) {
            __int128 num1 = cht[H - 2].b - cht[H - 1].b;
            __int128 den1 = cht[H - 1].a - cht[H - 2].a;
            __int128 num2 = cht[H - 1].b - unique_spells[i].b;
            __int128 den2 = unique_spells[i].a - cht[H - 1].a;
            if (num1 * den2 >= num2 * den1) {
                H--;
            } else {
                break;
            }
        }
        cht[H++] = unique_spells[i];
    }

    int Q = (int)read_ll();
    while (Q--) {
        long long x = read_ll();
        long long K_rem = K;
        long long cur_x = x;

        while (K_rem > 0) {
            int best_idx = query_cht(H, cur_x);
            if (best_idx == H - 1) {
                break;
            }
            cur_x = cht[best_idx].a * cur_x + cht[best_idx].b;
            K_rem--;
        }

        long long y = 0;
        if (K_rem == 0) {
            y = cur_x % MOD;
        } else {
            long long a_star = cht[H - 1].a;
            long long b_star = cht[H - 1].b % MOD;
            if (a_star == 1) {
                y = (cur_x + (__int128)(K_rem % MOD) * b_star) % MOD;
            } else {
                long long p = power_mod(a_star, K_rem);
                long long term1 = ((__int128)(cur_x % MOD) * p) % MOD;
                long long geom = ((__int128)(p - 1 + MOD) * mod_inv((a_star - 1) % MOD)) % MOD;
                long long term2 = ((__int128)b_star * geom) % MOD;
                y = (term1 + term2) % MOD;
            }
        }

        long long ans = ((__int128)A_ref * y + B_ref) % MOD;
        print_ll(ans);
    }

    return 0;
}
